const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

canvas.width = 400;
canvas.height = 550;

let player;
let bullets;
let enemies;
let score;
let lives;
let gameRunning = true;

let left = false;
let right = false;
let shooting = false;

let shootTimer = 0;
let enemyTimer = 0;

function startGame() {
    player = {
            x: 180,
                    y: 475,
                            width: 40,
                                    height: 40,
                                            speed: 5
                                                };

                                                    bullets = [];
                                                        enemies = [];
                                                            score = 0;
                                                                lives = 3;
                                                                    gameRunning = true;

                                                                        document.getElementById("gameOver").style.display = "none";

                                                                            update();
                                                                            }

                                                                            function drawPlayer() {
                                                                                ctx.fillStyle = "#00eaff";
                                                                                    ctx.fillRect(
                                                                                            player.x,
                                                                                                    player.y,
                                                                                                            player.width,
                                                                                                                    player.height
                                                                                                                        );

                                                                                                                            ctx.fillStyle = "white";
                                                                                                                                ctx.fillRect(player.x + 15, player.y - 10, 10, 15);
                                                                                                                                }

                                                                                                                                function drawBullets() {
                                                                                                                                    ctx.fillStyle = "#ffff00";

                                                                                                                                        bullets.forEach(b => {
                                                                                                                                                ctx.fillRect(b.x, b.y, 6, 15);
                                                                                                                                                        b.y -= 8;
                                                                                                                                                            });

                                                                                                                                                                bullets = bullets.filter(b => b.y > 0);
                                                                                                                                                                }

                                                                                                                                                                function createEnemy() {
                                                                                                                                                                    enemies.push({
                                                                                                                                                                            x: Math.random() * 360,
                                                                                                                                                                                    y: -30,
                                                                                                                                                                                            width: 35,
                                                                                                                                                                                                    height: 35,
                                                                                                                                                                                                            speed: 2 + Math.random() * 2
                                                                                                                                                                                                                });
                                                                                                                                                                                                                }

                                                                                                                                                                                                                function drawEnemies() {
                                                                                                                                                                                                                    ctx.fillStyle = "#ff3333";

                                                                                                                                                                                                                        enemies.forEach(e => {
                                                                                                                                                                                                                                ctx.fillRect(e.x, e.y, e.width, e.height);
                                                                                                                                                                                                                                        e.y += e.speed;

                                                                                                                                                                                                                                                // Colisão com o jogador
                                                                                                                                                                                                                                                        if (
                                                                                                                                                                                                                                                                    e.x < player.x + player.width &&
                                                                                                                                                                                                                                                                                e.x + e.width > player.x &&
                                                                                                                                                                                                                                                                                            e.y < player.y + player.height &&
                                                                                                                                                                                                                                                                                                        e.y + e.height > player.y
                                                                                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                                                                            e.y = 600;
                                                                                                                                                                                                                                                                                                                                        lives--;
                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                        enemies = enemies.filter(e => e.y < 570);
                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                        function checkCollisions() {
                                                                                                                                                                                                                                                                                                                                                            bullets.forEach((b, bi) => {
                                                                                                                                                                                                                                                                                                                                                                    enemies.forEach((e, ei) => {

                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                b.x < e.x + e.width &&
                                                                                                                                                                                                                                                                                                                                                                                                                b.x + 6 > e.x &&
                                                                                                                                                                                                                                                                                                                                                                                                                                b.y < e.y + e.height &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                b.y + 15 > e.y
                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            bullets.splice(bi, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            enemies.splice(ei, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            score += 10;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function update() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!gameRunning) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.clearRect(0, 0, canvas.width, canvas.height);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Movimento
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (left && player.x > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            player.x -= player.speed;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (right && player.x < canvas.width - player.width) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            player.x += player.speed;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Atirar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        shootTimer++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (shooting && shootTimer > 12) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    bullets.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                x: player.x + 17,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            y: player.y
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            shootTimer = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Criar inimigos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        enemyTimer++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (enemyTimer > 45) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    createEnemy();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            enemyTimer = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    drawPlayer();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawBullets();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            drawEnemies();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                checkCollisions();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("score").textContent = score;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("lives").textContent = lives;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (lives <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gameOver();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    requestAnimationFrame(update);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function gameOver() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gameRunning = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("finalScore").textContent = score;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("gameOver").style.display = "block";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function restartGame() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    startGame();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Teclado
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.addEventListener("keydown", e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (e.key === "ArrowLeft" || e.key === "a") left = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (e.key === "ArrowRight" || e.key === "d") right = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (e.code === "Space") shooting = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.addEventListener("keyup", e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (e.key === "ArrowLeft" || e.key === "a") left = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (e.key === "ArrowRight" || e.key === "d") right = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (e.code === "Space") shooting = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Controles para celular
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function control(id, action) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const button = document.getElementById(id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.addEventListener("pointerdown", e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    action(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.addEventListener("pointerup", () => action(false));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.addEventListener("pointerleave", () => action(false));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.addEventListener("pointercancel", () => action(false));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    control("left", v => left = v);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    control("right", v => right = v);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    control("fire", v => shooting = v);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    startGame();d